+/* ===== RESET & BASE ===== */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --bg-base:    #0c0c0e;
+  --bg-surface: #141417;
+  --bg-card:    #1b1b1f;
+  --bg-raised:  #222228;
+  --border:     #2e2e38;
+  --accent:     #e8b84b;
