}

/* ===== NEWSLETTER ===== */
.newsletter-section { background: var(--bg-surface); }
.newsletter-inner {
  max-width: 600px; margin: 0 auto;
  text-align: center; padding: 5rem 1.5rem;
}
.newsletter-icon {
  width: 56px; height: 56px; background: var(--accent-glow); border: 1px solid rgba(232,184,75,.2);
