  color: var(--accent);
}
.newsletter-title { font-family: var(--font-display); font-size: 2rem; font-weight: 700; margin-bottom: .75rem; }
.newsletter-subtitle { color: var(--text-secondary); font-size: .95rem; margin-bottom: 2rem; }
.newsletter-form { display: flex; gap: .75rem; }
.newsletter-input {
  flex: 1; background: var(--bg-card); border: 1px solid var(--border);
  color: var(--text-primary); padding: .75rem 1rem;
  border-radius: 999px; font-size: .9rem;
