}

a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; object-fit: cover; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg-base); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* ===== SKIP LINK ===== */
.skip-link {
  position: absolute; top: -100px; left: 1rem; z-index: 1000;
  background: var(--accent); color: #000; padding: .5rem 1rem;
  border-radius: var(--radius-sm); font-weight: 600; font-size: .875rem;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(12,12,14,.88);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  max-width: 1320px; margin: 0 auto;
  padding: 0 1.5rem;
  height: 68px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 2rem;
}

/* Logo */
.logo {
  display: flex; align-items: center; gap: .6rem;
  font-family: var(--font-display);
  font-size: 1.5rem; font-weight: 700; letter-spacing: .04em;
  color: var(--text-primary);
}
.logo-mark {
  width: 32px; height: 32px;
  background: var(--accent);
  border-radius: 6px;
  display: grid; place-items: center;
  color: #000; font-size: 1rem; font-weight: 900;
  font-family: var(--font-sans);
  flex-shrink: 0;
}

/* Search */
.search-form { position: relative; max-width: 420px; }
.search-input {
  width: 100%;
  background: var(--bg-card);
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: .55rem 1rem .55rem 2.75rem;
  border-radius: 999px;
  font-size: .9rem;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.search-input::placeholder { color: var(--text-muted); }
.search-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}
.search-icon {
  position: absolute; left: .9rem; top: 50%; transform: translateY(-50%);
  color: var(--text-muted); width: 16px; height: 16px; pointer-events: none;
}

/* Header actions */
.header-actions { display: flex; align-items: center; gap: .5rem; }
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  display: grid; place-items: center;
  color: var(--text-secondary);
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover, .icon-btn:focus-visible {
  background: var(--bg-raised);
  color: var(--text-primary);
  outline: none;
}
.icon-btn:focus-visible { box-shadow: 0 0 0 2px var(--accent); }
.badge {
  position: absolute; top: 5px; right: 5px;
  background: var(--accent); color: #000;
  font-size: .6rem; font-weight: 700;
  min-width: 16px; height: 16px; border-radius: 999px;
  display: grid; place-items: center; padding: 0 3px;
  line-height: 1;
}

/* Nav */
.primary-nav { display: flex; align-items: center; gap: .25rem; }
.primary-nav a {
  padding: .4rem .75rem; font-size: .875rem; font-weight: 500;
  color: var(--text-secondary); border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover, .primary-nav a:focus-visible {
  color: var(--text-primary); background: var(--bg-raised);
  outline: none;
}
.primary-nav a.active { color: var(--accent); }
.nav-bar {
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border);
}
.nav-bar-inner {
  max-width: 1320px; margin: 0 auto;
  padding: 0 1.5rem; height: 44px;
  display: flex; align-items: center; gap: 0;
}

/* ===== HERO ===== */
.hero {
  position: relative; overflow: hidden;
  min-height: 580px;
  display: grid; place-items: center;
}
.hero-bg {
  position: absolute; inset: 0; z-index: 0;
  background:
    radial-gradient(ellipse 80% 60% at 65% 50%, rgba(232,184,75,.08) 0%, transparent 70%),
    radial-gradient(ellipse 50% 80% at 20% 80%, rgba(100,80,232,.07) 0%, transparent 60%),
    linear-gradient(135deg, #0f0f13 0%, #12121a 100%);
}
.hero-grid-lines {
  position: absolute; inset: 0; z-index: 0;
  background-image:
    linear-gradient(rgba(255,255,255,.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.025) 1px, transparent 1px);
  background-size: 60px 60px;
}
.hero-content {
  position: relative; z-index: 1;
  max-width: 1320px; width: 100%; margin: 0 auto;
  padding: 5rem 1.5rem;
  display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: center;
}
.hero-eyebrow {
  font-size: .75rem; font-weight: 700; letter-spacing: .14em;
  text-transform: uppercase; color: var(--accent);
  display: flex; align-items: center; gap: .5rem; margin-bottom: 1rem;
}
.hero-eyebrow::before {
  content: ''; display: block; width: 24px; height: 2px; background: var(--accent);
}
.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 4.5vw, 3.6rem);
  font-weight: 700; line-height: 1.15;
  letter-spacing: -.01em;
  margin-bottom: 1.25rem;
}
.hero-title em { color: var(--accent); font-style: normal; }
.hero-subtitle {
  color: var(--text-secondary); font-size: 1.05rem;
  max-width: 440px; margin-bottom: 2rem; line-height: 1.7;
}
.hero-cta { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn-primary {
  background: var(--accent); color: #000;
  padding: .75rem 1.75rem; border-radius: 999px;
  font-weight: 700; font-size: .9rem; letter-spacing: .02em;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  display: inline-flex; align-items: center; gap: .5rem;
}
.btn-primary:hover, .btn-primary:focus-visible {
  background: #f0c96a;
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(232,184,75,.35);
  outline: none;
}
.btn-primary:focus-visible { box-shadow: 0 0 0 3px var(--accent-glow), 0 8px 24px rgba(232,184,75,.35); }
.btn-secondary {
  background: var(--bg-raised); color: var(--text-primary);
  border: 1px solid var(--border);
  padding: .75rem 1.75rem; border-radius: 999px;
  font-weight: 600; font-size: .9rem;
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
  display: inline-flex; align-items: center; gap: .5rem;
}
.btn-secondary:hover, .btn-secondary:focus-visible {
  background: #2c2c34; border-color: var(--text-muted);
  transform: translateY(-1px); outline: none;
}
.btn-secondary:focus-visible { box-shadow: 0 0 0 3px var(--accent-glow); }

/* Hero visual */
.hero-visual {
  display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;
}
.hero-card {
  border-radius: var(--radius-lg); overflow: hidden;
  aspect-ratio: 3/4; background: var(--bg-card);
  border: 1px solid var(--border);
  position: relative;
}
.hero-card:first-child { margin-top: 2rem; }
.hero-card-img { height: 100%; }
.hero-card-label {
  position: absolute; bottom: 1rem; left: 1rem; right: 1rem;
  background: rgba(12,12,14,.8); backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: var(--radius-md);
  padding: .75rem 1rem;
}
.hero-card-label strong { display: block; font-size: .875rem; margin-bottom: .2rem; }
.hero-card-label span { font-size: .75rem; color: var(--accent); }

/* ===== TRUST BAR ===== */
.trust-bar {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.trust-bar-inner {
  max-width: 1320px; margin: 0 auto;
  padding: 1rem 1.5rem;
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}
.trust-item {
  display: flex; align-items: center; gap: .75rem;
  padding: .75rem; border-radius: var(--radius-md);
}
.trust-icon {
  width: 36px; height: 36px; border-radius: 8px;
  background: var(--bg-raised); border: 1px solid var(--border);
  display: grid; place-items: center; flex-shrink: 0; color: var(--accent);
}
.trust-item strong { display: block; font-size: .85rem; }
.trust-item span { font-size: .75rem; color: var(--text-secondary); }

/* ===== SECTION COMMONS ===== */
.section { padding: 5rem 0; }
.section-inner { max-width: 1320px; margin: 0 auto; padding: 0 1.5rem; }
.section-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 2.5rem; gap: 1rem; flex-wrap: wrap;
}
.section-label {
  font-size: .7rem; font-weight: 700; letter-spacing: .14em;
  text-transform: uppercase; color: var(--accent); margin-bottom: .5rem;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 2.5vw, 2.2rem);
  font-weight: 700; line-height: 1.2;
}
.section-link {
  font-size: .875rem; font-weight: 600; color: var(--accent);
  display: inline-flex; align-items: center; gap: .35rem;
  transition: gap var(--transition);
  white-space: nowrap;
}
.section-link:hover, .section-link:focus-visible { gap: .6rem; outline: none; }
.section-link:focus-visible { box-shadow: 0 0 0 2px var(--accent); border-radius: 4px; padding: 2px 4px; }

/* ===== PRODUCT GRID ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

/* Product Card */
.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  display: flex; flex-direction: column;
}
.product-card:hover {
  border-color: rgba(232,184,75,.3);
  transform: translateY(-3px);
  box-shadow: var(--shadow-card), 0 0 0 1px rgba(232,184,75,.12);
}
.product-img-wrap {
  position: relative; background: var(--bg-raised); aspect-ratio: 4/5; overflow: hidden;
}
.product-img-wrap img { height: 100%; transition: transform .4s ease; }
.product-card:hover .product-img-wrap img { transform: scale(1.04); }
.product-badge {
  position: absolute; top: .75rem; left: .75rem;
  font-size: .65rem; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  padding: .25rem .6rem; border-radius: 999px;
}
.badge-new { background: var(--accent); color: #000; }
.badge-sale { background: var(--red); color: #fff; }
.badge-hot { background: #e87a4b; color: #fff; }
.badge-limited { background: var(--bg-raised); border: 1px solid var(--border); color: var(--text-secondary); }

.product-wishlist {
  position: absolute; top: .75rem; right: .75rem;
  width: 32px; height: 32px; border-radius: 50%;
  background: rgba(20,20,23,.8); backdrop-filter: blur(8px);
  border: 1px solid var(--border);
  display: grid; place-items: center;
  color: var(--text-muted);
  transition: color var(--transition), background var(--transition), border-color var(--transition);
}
.product-wishlist:hover, .product-wishlist.active { color: #e84b4b; }
.product-wishlist.active { background: rgba(232,75,75,.15); border-color: rgba(232,75,75,.4); }
.product-wishlist:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.product-info { padding: 1rem 1.1rem 1.1rem; flex: 1; display: flex; flex-direction: column; }
.product-brand { font-size: .7rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--text-muted); margin-bottom: .3rem; }
.product-name { font-size: .95rem; font-weight: 600; line-height: 1.35; margin-bottom: .6rem; flex: 1; }
.product-rating { display: flex; align-items: center; gap: .4rem; margin-bottom: .75rem; }
.stars { display: flex; gap: 2px; }
.star { color: var(--accent); font-size: .7rem; }
.star.empty { color: var(--bg-raised); }
.rating-count { font-size: .72rem; color: var(--text-secondary); }
.product-pricing { display: flex; align-items: baseline; gap: .6rem; margin-bottom: 1rem; }
.price-current { font-size: 1.1rem; font-weight: 700; color: var(--text-primary); }
.price-original { font-size: .85rem; color: var(--text-muted); text-decoration: line-through; }
.price-save { font-size: .72rem; color: var(--green); font-weight: 600; }
.product-add {
  width: 100%; padding: .65rem; border-radius: var(--radius-sm);
  background: var(--bg-raised); border: 1px solid var(--border);
  color: var(--text-primary); font-weight: 600; font-size: .85rem;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  display: flex; align-items: center; justify-content: center; gap: .5rem;
}
.product-add:hover, .product-add:focus-visible {
  background: var(--accent); color: #000; border-color: var(--accent); outline: none;
}
.product-add:focus-visible { box-shadow: 0 0 0 3px var(--accent-glow); }
.product-add.added {
  background: rgba(75,232,149,.15); border-color: rgba(75,232,149,.4); color: var(--green);
}

/* ===== DEALS SECTION ===== */
.deals-section { background: var(--bg-surface); }
.deals-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem;
}
.deal-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-card);
  border: 1px solid var(--border);
  display: grid; grid-template-columns: 1fr 1fr;
  min-height: 260px;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.deal-card:hover { border-color: rgba(232,75,75,.35); box-shadow: 0 8px 32px rgba(0,0,0,.4); }
.deal-card.featured {
  grid-column: 1 / -1; grid-template-columns: 1fr 1fr;
}
.deal-img { aspect-ratio: auto; height: 100%; min-height: 200px; }
.deal-body {
  padding: 1.75rem; display: flex; flex-direction: column; justify-content: center;
}
.deal-tag {
  display: inline-flex; align-items: center; gap: .4rem;
  font-size: .68rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--red); margin-bottom: .75rem;
}
.deal-tag::before {
  content: ''; display: block; width: 6px; height: 6px; border-radius: 50%; background: var(--red);
}
.deal-title { font-family: var(--font-display); font-size: 1.3rem; font-weight: 700; margin-bottom: .5rem; line-height: 1.25; }
.deal-desc { font-size: .85rem; color: var(--text-secondary); margin-bottom: 1.25rem; line-height: 1.6; }
.deal-price-row { display: flex; align-items: baseline; gap: .75rem; margin-bottom: 1.25rem; }
.deal-price { font-size: 1.5rem; font-weight: 800; color: var(--red); }
.deal-original { font-size: .95rem; color: var(--text-muted); text-decoration: line-through; }
.deal-save-badge {
  background: rgba(232,75,75,.15); border: 1px solid rgba(232,75,75,.3);
  color: var(--red); font-size: .72rem; font-weight: 700;
  padding: .2rem .6rem; border-radius: 999px;
}
.deal-timer { display: flex; align-items: center; gap: .5rem; margin-bottom: 1.25rem; }
.deal-timer-label { font-size: .72rem; color: var(--text-muted); font-weight: 600; text-transform: uppercase; letter-spacing: .06em; }
.timer-segments { display: flex; gap: .3rem; }
.timer-seg {
  background: var(--bg-raised); border: 1px solid var(--border);
  border-radius: 6px; padding: .3rem .5rem; text-align: center; min-width: 38px;
}
.timer-seg span { display: block; font-size: .95rem; font-weight: 700; line-height: 1; font-variant-numeric: tabular-nums; }
.timer-seg small { display: block; font-size: .55rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: .06em; margin-top: 2px; }
.btn-deal {
  background: var(--red); color: #fff;
  padding: .65rem 1.5rem; border-radius: 999px;
  font-weight: 700; font-size: .875rem;
  display: inline-flex; align-items: center; gap: .5rem;
  align-self: flex-start;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn-deal:hover, .btn-deal:focus-visible {
  background: #f05f5f; transform: translateY(-1px);
  box-shadow: 0 8px 20px rgba(232,75,75,.35); outline: none;
}
.btn-deal:focus-visible { box-shadow: 0 0 0 3px rgba(232,75,75,.3), 0 8px 20px rgba(232,75,75,.35); }

/* ===== CATEGORIES ===== */
.category-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}
.category-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  display: flex; flex-direction: column;
  transition: border-color var(--transition), transform var(--transition);
  text-align: center;
}
.category-card:hover, .category-card:focus-visible {
  border-color: rgba(232,184,75,.35); transform: translateY(-2px); outline: none;
}
.category-card:focus-visible { box-shadow: 0 0 0 2px var(--accent); }
.category-img { aspect-ratio: 1; background: var(--bg-raised); }
.category-name { padding: .75rem .5rem; font-size: .8rem; font-weight: 600; }

/* ===== EDITORIAL ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 1.5rem;
}
.editorial-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  display: flex; flex-direction: column;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.editorial-card:hover { border-color: rgba(232,184,75,.25); transform: translateY(-3px); box-shadow: var(--shadow-card); }
.editorial-card:focus-within { border-color: var(--accent); }
.editorial-img { aspect-ratio: 16/9; background: var(--bg-raised); }
.editorial-card.featured .editorial-img { aspect-ratio: 4/3; }
.editorial-body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; }
.editorial-tag {
  font-size: .68rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--accent); margin-bottom: .6rem;
}
.editorial-title {
  font-family: var(--font-display);
  font-size: 1.15rem; font-weight: 700; line-height: 1.3; margin-bottom: .6rem; flex: 1;
}
.editorial-card.featured .editorial-title { font-size: 1.5rem; }
.editorial-excerpt { font-size: .83rem; color: var(--text-secondary); line-height: 1.65; margin-bottom: 1rem; }
.editorial-meta { display: flex; align-items: center; gap: .75rem; margin-top: auto; }
.editorial-author { display: flex; align-items: center; gap: .5rem; }
.author-avatar {
  width: 28px; height: 28px; border-radius: 50%; background: var(--bg-raised);
  border: 1px solid var(--border); overflow: hidden; flex-shrink: 0;
  display: grid; place-items: center; font-size: .65rem; font-weight: 700; color: var(--accent);
}
.author-name { font-size: .78rem; font-weight: 600; }
.editorial-date { font-size: .72rem; color: var(--text-muted); margin-left: auto; }
.editorial-read {
  font-size: .78rem; font-weight: 700; color: var(--accent);
  display: inline-flex; align-items: center; gap: .3rem; margin-top: .75rem;
  transition: gap var(--transition);
}
.editorial-read:hover, .editorial-read:focus-visible { gap: .55rem; outline: none; }
.editorial-read:focus-visible { box-shadow: 0 0 0 2px var(--accent); border-radius: 4px; padding: 2px 4px; }

/* ===== BANNER ===== */
.promo-banner {
  background: linear-gradient(135deg, #1a1408 0%, #1e1610 40%, #12120e 100%);
  border: 1px solid rgba(232,184,75,.2);
  border-radius: var(--radius-lg);
  padding: 3.5rem 3rem;
  display: grid; grid-template-columns: 1fr auto; gap: 2rem; align-items: center;
  position: relative; overflow: hidden;
}
.promo-banner::before {
  content: '';
  position: absolute; right: -60px; top: -60px;
  width: 300px; height: 300px;
  background: radial-gradient(circle, rgba(232,184,75,.1) 0%, transparent 70%);
}
.promo-eyebrow { font-size: .72rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--accent); margin-bottom: .75rem; }
.promo-title { font-family: var(--font-display); font-size: clamp(1.6rem, 3vw, 2.4rem); font-weight: 700; margin-bottom: .75rem; }
.promo-subtitle { font-size: .95rem; color: var(--text-secondary); }
.promo-code-wrap { display: flex; align-items: center; gap: 1rem; margin-top: 1.5rem; flex-wrap: wrap; }
.promo-code {
  background: var(--bg-card); border: 2px dashed rgba(232,184,75,.4);
  color: var(--accent); padding: .5rem 1.25rem; border-radius: var(--radius-sm);
  font-size: 1.1rem; font-weight: 800; letter-spacing: .1em;
}
.copy-btn {
  background: var(--accent); color: #000;
  padding: .5rem 1rem; border-radius: var(--radius-sm);
  font-weight: 700; font-size: .8rem;
  transition: background var(--transition);
}
.copy-btn:hover, .copy-btn:focus-visible { background: #f0c96a; outline: none; }
.copy-btn:focus-visible { box-shadow: 0 0 0 3px var(--accent-glow); }
.promo-visual { text-align: right; }
.promo-pct {
  font-family: var(--font-display); font-size: 6rem; font-weight: 900; line-height: 1;
  color: transparent;
  -webkit-text-stroke: 2px rgba(232,184,75,.3);
  user-select: none;
}

/* ===== NEWSLETTER ===== */
.newsletter-section { background: var(--bg-surface); }
.newsletter-inner {
  max-width: 600px; margin: 0 auto;
  text-align: center; padding: 5rem 1.5rem;
}
.newsletter-icon {
  width: 56px; height: 56px; background: var(--accent-glow); border: 1px solid rgba(232,184,75,.2);
  border-radius: var(--radius-md); display: grid; place-items: center; margin: 0 auto 1.5rem;
