          <span class="rating-count">(${reviews})</span>
        </div>
        <div class="product-pricing">
          <span class="price-current" aria-label="Current price: $${price}">$${price}</span>
          ${originalPrice ? `<span class="price-original" aria-label="Original price: $${originalPrice}">$${originalPrice}</span>` : ''}
          ${savings ? `<span class="price-save" aria-label="Save ${savings} percent">−${savings}%</span>` : ''}
        </div>
        <button class="product-add" data-add-id="${id}" data-add-name="${name}">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true">
            <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/>
