// ── Countdown Timer ───────────────────────────
function initTimers() {
  const targets = {
    deal1: new Date(Date.now() + (6 * 3600 + 42 * 60 + 17) * 1000),
    deal2: new Date(Date.now() + (1 * 86400 + 3 * 3600 + 15 * 60 + 8) * 1000),
  };

  function pad(n) { return String(n).padStart(2, '0'); }

  function updateTimer(id, target) {
    const el = document.getElementById(`timer-${id}`);
    if (!el) return;
    const diff = Math.max(0, target - Date.now());
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    const d = Math.floor(h / 24);
    const hh = h % 24;

    if (d > 0) {
      el.innerHTML = `
        <div class="timer-seg"><span>${pad(d)}</span><small>Days</small></div>
        <div class="timer-seg"><span>${pad(hh)}</span><small>Hrs</small></div>
        <div class="timer-seg"><span>${pad(m)}</span><small>Min</small></div>
        <div class="timer-seg"><span>${pad(s)}</span><small>Sec</small></div>`;
    } else {
      el.innerHTML = `
        <div class="timer-seg"><span>${pad(h)}</span><small>Hrs</small></div>
        <div class="timer-seg"><span>${pad(m)}</span><small>Min</small></div>
        <div class="timer-seg"><span>${pad(s)}</span><small>Sec</small></div>`;
    }
  }

  function tick() {
    Object.entries(targets).forEach(([id, t]) => updateTimer(id, t));
  }
  tick();
  setInterval(tick, 1000);
}

// ── Promo Code Copy ───────────────────────────
function initPromoCode() {
  const copyBtn = $('#copy-promo');
  if (!copyBtn) return;
  copyBtn.addEventListener('click', async () => {
    const code = copyBtn.dataset.code;
    try {
      await navigator.clipboard.writeText(code);
      copyBtn.textContent = 'Copied!';
      showToast(`Promo code <strong>${code}</strong> copied`);
    } catch {
      copyBtn.textContent = 'Copied!';
      showToast(`Use code <strong>${code}</strong> at checkout`);
    }
    setTimeout(() => { copyBtn.textContent = 'Copy Code'; }, 2000);
  });
}

// ── Newsletter ────────────────────────────────
function initNewsletter() {
  const form = $('#newsletter-form');
  if (!form) return;
  form.addEventListener('submit', e => {
    e.preventDefault();
    const email = form.querySelector('input[type="email"]');
    if (!email.value) return;
    showToast(`🎉 You're subscribed with <strong>${email.value}</strong>`);
    email.value = '';
  });
}

// ── Search ────────────────────────────────────
function initSearch() {
  const input = $('#search-input');
  if (!input) return;
  input.addEventListener('keydown', e => {
    if (e.key === 'Enter' && input.value.trim()) {
      showToast(`Searching for "<strong>${input.value}</strong>"…`);
    }
  });
}

// ── Scroll Animations ─────────────────────────
function initScrollAnimations() {
  if (!('IntersectionObserver' in window)) return;
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.style.opacity = '1';
        entry.target.style.transform = 'translateY(0)';
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.08 });

  $$('.product-card, .deal-card, .editorial-card, .category-card, .trust-item').forEach((el, i) => {
    el.style.opacity = '0';
    el.style.transform = 'translateY(18px)';
    el.style.transition = `opacity .45s ease ${i * 0.04}s, transform .45s ease ${i * 0.04}s, border-color .22s cubic-bezier(.4,0,.2,1), box-shadow .22s cubic-bezier(.4,0,.2,1)`;
    observer.observe(el);
  });
}

// ── Deals ─────────────────────────────────────
function bindDealButtons() {
  $$('.btn-deal').forEach(btn => {
    btn.addEventListener('click', () => {
      const name = btn.dataset.dealName || 'this item';
      state.cartCount++;
      updateCartBadge();
      showToast(`<strong>${name}</strong> added to cart`);
    });
  });
}

// ── Init ──────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  renderFeaturedProducts();
  initTimers();
  initPromoCode();
  initNewsletter();
  initSearch();
  bindDealButtons();
  // slight delay to ensure DOM is painted before attaching observers
  requestAnimationFrame(initScrollAnimations);
});
